-- Keep legacy task tables compatible while retaining the configured work-item type.
SET @schema_name = DATABASE();
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='t_product_requirement' AND column_name='work_item_type_id_')=0, 'ALTER TABLE t_product_requirement ADD COLUMN work_item_type_id_ VARCHAR(36) NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='t_product_design_task' AND column_name='work_item_type_id_')=0, 'ALTER TABLE t_product_design_task ADD COLUMN work_item_type_id_ VARCHAR(36) NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='t_product_dev_task' AND column_name='work_item_type_id_')=0, 'ALTER TABLE t_product_dev_task ADD COLUMN work_item_type_id_ VARCHAR(36) NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='t_product_bug' AND column_name='work_item_type_id_')=0, 'ALTER TABLE t_product_bug ADD COLUMN work_item_type_id_ VARCHAR(36) NULL', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
